// Browser preview: the screens, played back from a snapshot of what the
// stand-in daemon says (fixture.json, generated by a Rust test). Loaded
// only when the page is NOT inside the Tauri app — for reviews and cloud
// sessions, which can't open the Mac window. Nothing here runs an agent.

import { emit } from "@tauri-apps/api/event";
import { mockIPC } from "@tauri-apps/api/mocks";
import type { AgentView } from "../bindings/AgentView";
import type { FileNode } from "../bindings/FileNode";
import type { MountsView } from "../bindings/MountsView";
import type { VolumeStat } from "../bindings/VolumeStat";
import type { CardView } from "../bindings/CardView";
import type { KnockView } from "../bindings/KnockView";
import type { MoveView } from "../bindings/MoveView";
import type { SpaceView } from "../bindings/SpaceView";
import type { LogEntry } from "../bindings/LogEntry";
import type { MachineView } from "../bindings/MachineView";
import type { SavedView } from "../bindings/SavedView";
import type { LocalAgentView } from "../bindings/LocalAgentView";
import type { TabKind } from "../bindings/TabKind";
import type { TabView } from "../bindings/TabView";
import fixture from "./fixture.json";

type Chan = { onmessage: (e: unknown) => void };
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Args = Record<string, any>;

export const PREVIEW_HOST = "browser-preview";

type Invite = { host: { kind: string; address?: string; identity?: string }; id: string; secret?: string; title: string; kind: string; host_name: string; charter: string; verbs: { name: string; does: string }[] };

function decodeInvite(text: string): Invite | null {
  try {
    const body = String(text).trim().replace(/^diverge-invite:/, "").replace(/-/g, "+").replace(/_/g, "/");
    return JSON.parse(decodeURIComponent(escape(atob(body + "===".slice((body.length + 3) % 4)))));
  } catch {
    return null;
  }
}

function encodeInvite(invite: Invite): string {
  return "diverge-invite:" + btoa(unescape(encodeURIComponent(JSON.stringify(invite)))).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

export function installPreview() {
  const agents: AgentView[] = structuredClone(fixture.agents) as AgentView[];
  const logs: Record<string, LogEntry[]> = structuredClone(fixture.logs) as Record<string, LogEntry[]>;
  const machines: MachineView[] = structuredClone(fixture.machines) as MachineView[];
  // Per machine (by identity key): its files ("volume:path"), trees, and stats.
  const files = structuredClone(fixture.files) as Record<string, Record<string, string>>;
  const trees = structuredClone(fixture.trees) as Record<string, Record<string, FileNode[]>>;
  const stats = structuredClone(fixture.stats) as Record<string, Record<string, VolumeStat>>;
  const mounts = structuredClone(fixture.mounts) as Record<string, MountsView>;
  const machineKey = (p: { kind: string; address?: string; identity?: string }) => (p.kind === "outgoing" ? `outgoing:${p.address}` : `incoming:${p.identity}`);
  const machineOf = (p: { kind: string }) => machines.find((m) => machineKey(m.identity) === machineKey(p));
  const volumesOf = (p: { kind: string }) => machineOf(p)?.volumes ?? [];
  const views: SavedView[] = [];
  const localAgents: LocalAgentView[] = [];
  type SpaceRec = { view: SpaceView; moves: MoveView[]; invite: string | null; from_copy?: boolean };
  const spaceRecs: SpaceRec[] = structuredClone(fixture.spaces) as SpaceRec[];
  const knocks: KnockView[] = structuredClone(fixture.knocks) as KnockView[];
  const you = fixture.you as { name: string; key: string };
  const personas = structuredClone(fixture.personas) as { id: string; name: string; usual: boolean; rooms: string[] }[];
  const tables = structuredClone(fixture.tables) as Record<string, { nodes: FileNode[]; files: Record<string, string> }>;
  const allowances: Record<string, Record<string, number>> = {};
  const cards: CardView[] = structuredClone(fixture.cards) as CardView[];
  // Cards withdrawn because their agent stopped waiting: an answer to one does nothing.
  const withdrawn = new Set<number>();
  let cardCh: Chan | null = null;
  const spaceWatches = new Map<string, { id: string; ch: Chan }>();
  let knockCh: Chan | null = null;
  let moveN = 1000;
  const spaceOf = (id: string) => spaceRecs.find((r) => r.view.summary.id === id);
  // Your own home and profile, by kind: a room's id is its host's, not a fixed name.
  const yours = (kind: string) => spaceRecs.find((r) => r.view.summary.mine && r.view.summary.kind === kind)?.view.summary.id ?? null;
  const bump = (id: string) => {
    for (const w of spaceWatches.values()) if (w.id === id) w.ch.onmessage({ event: "updated", uri: "space://feed" });
  };
  const watches = new Map<string, { name: string; ch: Chan }>();
  const pending = new Map<string, { resolve: (v: unknown) => void; timer: number }>();
  let tabs: TabView[] = [];
  let focused: string | null = null;
  let generation = 0;
  let scope = 0;

  const keyOf = (tab: TabKind) =>
    tab.kind === "agent" ? `agent:${tab.name}` : tab.kind === "space" ? `space:${tab.id}` : tab.kind === "door" ? `door:${tab.invite.slice(-16)}` : tab.kind.replace("_", "-");
  const snapshot = () => ({ generation, tabs, focused });
  const later = (fn: () => void) => setTimeout(fn, 0);
  const push = (name: string, entry: LogEntry) => {
    (logs[name] ??= []).push(entry);
    for (const w of watches.values()) if (w.name === name) w.ch.onmessage({ event: "entry", entry });
  };

  mockIPC(
    async (cmd: string, args: Args = {}) => {
      switch (cmd) {
        case "app_info":
          // Preview only: add ?folder-in-use to the address to see how a second copy of the app says so.
          return {
            stand_in: true,
            network: true,
            contract_pin: fixture.contract_pin,
            stand_in_host: PREVIEW_HOST,
            folder: "~/Library/Application Support/network.diverge.desktop.draft",
            folder_held: new URLSearchParams(location.search).has("folder-in-use") ? { state: "in_use" } : { state: "yes" },
          };
        case "actions_list":
          return fixture.actions;
        case "catalog_images":
          return fixture.catalog;
        case "catalog_check":
          return null;
        case "agents_list":
          return { agents, errors: [] };
        case "agents_create": {
          const input = args.input;
          if (agents.some((a) => a.name === input.name)) return { outcome: "in_use" };
          agents.push({ name: input.name, image_name: `diverge-agentic-loop-${input.image_kind}`, digest: "unbuilt", created: new Date().toISOString(), active: false, last_active: null, provider: null, logs_index: 0, tools: [] });
          logs[input.name] = [];
          const view = (m: { provider?: unknown; volume_name: string; volume_relative_path: string; volume_mode: string; container_path: string }) => ({ ...m, provider: m.provider ?? null });
          mounts[input.name] = { pinned: input.provider, volume_mounts: input.volume_mounts.map(view), fuse_file_mounts: input.fuse_file_mounts.map(view), fuse_directory_mounts: input.fuse_directory_mounts.map(view) } as MountsView;
          return { outcome: "created" };
        }
        case "agents_delete": {
          const a = agents.find((x) => x.name === args.name);
          if (!a) return { outcome: "not_found" };
          if (a.active) return { outcome: "active" };
          agents.splice(agents.indexOf(a), 1);
          tabs = tabs.filter((t) => t.key !== `agent:${args.name}`);
          generation++;
          emit("tabs://changed", snapshot());
          return { outcome: "deleted" };
        }
        case "agents_mounts":
          return mounts[args.name] ?? null;
        case "agents_edit": {
          const input = args.input;
          const a = agents.find((x) => x.name === input.name);
          if (!a) return { outcome: "not_found" };
          if (a.active) return { outcome: "active" };
          const before = mounts[input.name];
          if (!before) return { outcome: "error", message: "not known here" };
          const view = (m: { provider?: unknown; volume_name: string; volume_relative_path: string; volume_mode: string; container_path: string }) => ({ ...m, provider: m.provider ?? null });
          mounts[input.name] = { pinned: before.pinned, volume_mounts: input.volume_mounts.map(view), fuse_file_mounts: input.fuse_file_mounts.map(view), fuse_directory_mounts: input.fuse_directory_mounts.map(view) } as MountsView;
          return { outcome: "edited" };
        }
        case "agents_message":
          return new Promise((resolve) => {
            const timer = window.setTimeout(() => {
              pending.delete(args.ticket);
              const list = logs[args.name] ?? [];
              push(args.name, { logs_index: (list[list.length - 1]?.logs_index ?? 0) + 1, created: new Date().toISOString(), item: { kind: "user_text", key: args.ticket, text: args.text } });
              resolve({ outcome: "delivered" });
            }, 2500);
            pending.set(args.ticket, { resolve, timer });
          });
        case "agents_message_take_back": {
          const p = pending.get(args.ticket);
          if (!p) return false;
          clearTimeout(p.timer);
          pending.delete(args.ticket);
          p.resolve({ outcome: "cancelled" });
          return true;
        }
        case "logs_open": {
          const id = `logs-${++scope}`;
          const q = args.query;
          const ch = args.onEvent as Chan;
          later(() => {
            for (const entry of logs[q.name] ?? []) {
              if (q.logs_index_from && entry.logs_index < q.logs_index_from) continue;
              if (q.logs_index_to && entry.logs_index > q.logs_index_to) continue;
              if (q.item_type && !matchesType(entry, q.item_type)) continue;
              ch.onmessage(q.jq ? { event: "value", value: "(jq runs in the app, not the browser preview)" } : { event: "entry", entry });
            }
            if (q.watch) watches.set(id, { name: q.name, ch });
            else ch.onmessage({ event: "end" });
          });
          return id;
        }
        case "scope_close":
          return watches.delete(args.id);
        case "volumes_list":
          return machineOf(args.machine) ? { outcome: "volumes", volumes: volumesOf(args.machine) } : { outcome: "error", message: "the daemon knows no machine by that identity" };
        case "volumes_stat": {
          const k = machineKey(args.machine);
          const v = volumesOf(args.machine).find((x) => x.name === args.name);
          if (!v) return { outcome: "error", message: `no volume named "${args.name}"` };
          const known = stats[k]?.[args.name];
          if (known && known.outcome === "error") return known;
          const used = Object.entries(files[k] ?? {}).filter(([p]) => p.startsWith(`${args.name}:`)).reduce((n, [, text]) => n + new TextEncoder().encode(text).length, 0);
          return { outcome: "stat", volume: v, bytes_used: used };
        }
        case "volumes_tree": {
          const k = machineKey(args.machine);
          const held = stats[k]?.[args.name];
          if (held && held.outcome === "error") return held;
          return trees[k]?.[args.name] ? { outcome: "tree", nodes: trees[k][args.name] } : { outcome: "error", message: `no volume named "${args.name}"` };
        }
        case "volumes_read": {
          const text = files[machineKey(args.machine)]?.[`${args.name}:${args.path}`];
          return text === undefined ? { outcome: "error", message: `${args.path}: not in the preview snapshot` } : { outcome: "text", text, bytes: new TextEncoder().encode(text).length };
        }
        case "volumes_write": {
          const k = machineKey(args.machine);
          (files[k] ??= {})[`${args.name}:${args.path}`] = args.text;
          return { outcome: "written" };
        }
        case "volumes_room":
          return { outcome: "capacity", bytes: 64 * 1024 ** 3 - volumesOf(args.machine).reduce((n, v) => n + v.bytes, 0) };
        case "volumes_room_for":
          return { outcome: "capacity", bytes: 64 * 1024 ** 3 };
        case "volumes_create": {
          const m = machineOf(args.machine);
          if (!m) return { outcome: "error", message: "the daemon knows no machine by that identity" };
          m.volumes.push({ name: args.name, bytes: args.bytes, created: new Date().toISOString(), mode: args.mode });
          ((trees[machineKey(args.machine)] ??= {}))[args.name] = [];
          return { outcome: "done" };
        }
        case "volumes_edit": {
          const v = volumesOf(args.machine).find((x) => x.name === args.name);
          if (v && args.bytes !== null) v.bytes = args.bytes;
          if (v && args.mode !== null) v.mode = args.mode;
          return { outcome: "done" };
        }
        case "volumes_delete": {
          const k = machineKey(args.machine);
          if (stats[k]?.[args.name]?.outcome === "error") return { outcome: "in_use" };
          const list = volumesOf(args.machine);
          list.splice(list.findIndex((x) => x.name === args.name), 1);
          return { outcome: "done" };
        }
        case "profile_get": {
          const mineKeys = new Set(personas.map(() => you.key));
          const seen = new Set<string>();
          const receipts = spaceRecs.flatMap((r) =>
            r.moves
              .filter((m) => m.kind === "receipt")
              .map((m) => ({ m, st: (m.fields as Record<string, unknown>).statement as { key: string; sig: string; body: Record<string, string> } | undefined }))
              .filter(({ st }) => st && mineKeys.has(st.body.to_person) && !seen.has(st.sig) && seen.add(st.sig))
              .map(({ m, st }) => ({
                title: m.title,
                for_title: m.body.replace(/^Completed: /, ""),
                room_title: st!.body.room_title,
                space: spaceRecs.find((x) => x.view.summary.id === st!.body.room)?.view.summary ?? null,
                to: st!.body.to_name,
                at: m.at,
                issued_by: st!.body.host,
                known: true,
                holds: true,
                earned_as: you.name,
                earned_as_usual: true,
              })),
          );
          const profileId = yours("profile");
          const profile = profileId ? spaceOf(profileId) : undefined;
          return { receipts, shows: profile ? profile.moves.filter((m) => m.kind === "show") : [], agents, machines, volumes: machines.flatMap((m) => m.volumes), home: yours("home"), profile: profileId, personas };
        }
        case "people_list": {
          const people = new Map<string, { name: string; key: string; is_agent: boolean; agent_of: string | null; spaces: string[] }>();
          for (const r of spaceRecs) for (const m of r.view.members) {
            if (!m.key || m.key === you.key || (m.is_agent && m.agent_of === you.name)) continue;
            const p = people.get(m.key) ?? { name: m.name, key: m.key, is_agent: m.is_agent, agent_of: m.agent_of, spaces: [] };
            p.spaces.push(r.view.summary.id);
            people.set(m.key, p);
          }
          return [...people.values()];
        }
        case "personas_list":
          return personas;
        case "persona_rename": {
          const q = personas.find((x) => x.id === args.id);
          if (q) q.name = args.name;
          return null;
        }
        case "allowance_get":
          return { per_day: allowances[`${args.id}/${args.agent}`] ?? {}, used_today: {} };
        case "allowance_set":
          allowances[`${args.id}/${args.agent}`] = { ...(allowances[`${args.id}/${args.agent}`] ?? {}), [args.reach]: args.perDay };
          return { per_day: args.perDay, used_today: 0 };
        case "spaces_home":
          return yours("home");
        case "home_feed":
          return spaceRecs.flatMap((r) => r.moves.map((entry) => ({ space: r.view.summary, entry }))).sort((a, b) => b.entry.at.localeCompare(a.entry.at));
        case "spaces_list":
          return spaceRecs.map((r) => r.view.summary);
        case "spaces_get": {
          const r = spaceOf(args.id);
          if (!r) throw new Error("no such Space");
          return r.view;
        }
        case "spaces_feed": {
          const r = spaceOf(args.id);
          return r ? { outcome: "feed", moves: r.moves, from_copy: Boolean(r.from_copy) } : { outcome: "error", message: "no such Space" };
        }
        case "spaces_doorways": {
          const r = spaceOf(args.id);
          return (r?.moves ?? []).filter((m) => m.kind === "doorway").map((m) => ({ title: m.title, invite: m.body, by: m.author, at: m.at }));
        }
        case "first_run_get": {
          // Preview only: add ?first-run (or ?first-run=earlier) to the address to see the first-run page.
          const asked = new URLSearchParams(location.search).get("first-run");
          if (asked === null) return { state: "done" };
          return asked === "earlier" ? { state: "earlier", name: you.name } : { state: "new" };
        }
        case "first_run_finish":
          return { state: "done" };
        case "identity_broken":
          // Preview only: add ?keys-unreadable to the address to see how the app says so.
          return new URLSearchParams(location.search).has("keys-unreadable") ? { file: "~/Library/Application Support/network.diverge.desktop.draft/identity.json", newer: false } : null;
        case "files_set_aside":
          // Preview only: add ?files-set-aside to the address to see how the app says so.
          return new URLSearchParams(location.search).has("files-set-aside")
            ? [
                { kind: "views", room: null, last_good_copy: false, file: "~/Library/Application Support/network.diverge.desktop.draft/views.json", why: "newer", kept_as: "~/Library/Application Support/network.diverge.desktop.draft/views.newer-v2-20260930120000.json", error: null, carried_on: "last_good" },
                { kind: "record copy", room: "Saturday Workshop", last_good_copy: false, file: "~/Library/Application Support/network.diverge.desktop.draft/records/5f1c0e.json", why: "refused", kept_as: "~/Library/Application Support/network.diverge.desktop.draft/records/5f1c0e.refused-20260930120000.json", error: null, carried_on: "last_good" },
                { kind: "machine names", room: null, last_good_copy: false, file: "~/Library/Application Support/network.diverge.desktop.draft/machine_names.json", why: "unread", kept_as: null, error: "Permission denied (os error 13)", carried_on: "nothing_this_launch" },
              ]
            : [];
        case "asks_close":
          return [];
        case "vouch_for":
          return "diverge-vouch:" + btoa(JSON.stringify({ kind: "vouch", body: { for: args.key, for_name: args.name, by_name: you.name }, key: you.key, sig: "preview" })).replace(/=+$/, "");
        case "spaces_admitted": {
          const r = spaceOf(args.id);
          return (r?.view.members ?? []).map((m) => ({ name: m.name, key: m.key, listed: true, is_agent: m.is_agent, yours: m.is_agent && m.agent_of_key === you.key, mark: m.mark ?? null }));
        }
        case "spaces_restart": {
          // A restart to shut someone out: the room's invite gets a new secret.
          const r = spaceOf(args.id);
          const old = r?.invite ? decodeInvite(r.invite) : null;
          if (!r || !old) throw new Error("only its host restarts a room");
          r.invite = encodeInvite({ ...old, secret: `${old.id}-${Date.now()}` });
          return { text: r.invite };
        }
        case "spaces_continue": {
          const r = spaceOf(args.id);
          if (!r) return { outcome: "error", message: "you hold no copy of that room" };
          const id = `space-${Date.now()}`;
          const summary = { ...r.view.summary, id, title: `${r.view.summary.title}, continued`, host: { kind: "outgoing", address: "127.0.0.1:4640" }, host_name: you.name, mine: true, online: true } as SpaceView["summary"];
          spaceRecs.push({ view: { ...r.view, summary, members: [{ name: you.name, key: you.key, is_agent: false, agent_of: null, agent_of_key: null, joined: new Date().toISOString(), last_acted: null, mark: null, devices: [], slot: null }], tools: spaceRecs[0]?.view.tools ?? [], before: [] }, moves: r.moves.map((m) => ({ ...m, fields: { ...(m.fields as object), from: r.view.summary.title } })), invite: null });
          return { outcome: "hosted", id };
        }
        case "spaces_call": {
          const r = spaceOf(args.id);
          if (!r) return { outcome: "error", message: "no such Space" };
          const a = (args.arguments ?? {}) as Record<string, string>;
          const now = new Date().toISOString();
          const push = (kind: string, title: string, body: string, state: string, parent: string | null, fields: Record<string, unknown> = {}) => {
            const id = `${kind}-${++moveN}`;
            r.moves.push({ id, kind, author: r.view.summary.you_are, by: r.view.summary.you_key, member: null, erasable: false, agent_of: null, at: now, title, body, state, parent, fields, charter: "", hash: "" });
            return id;
          };
          const find = (id: string) => r.moves.find((m) => m.id === id);
          let line = "";
          switch (args.tool) {
            case "show": line = `Shown: ${a.title} (${push("show", a.title, a.body ?? "", "shown", null)})`; break;
            case "ask": line = `Asked: ${a.what} (${push("ask", a.what, "", "open", null, { needs: a.needs, ceiling: a.ceiling, who_may_serve: a.who_may_serve, thread: a.thread })})`; break;
            case "offer": { const q = find(a.ask_id); line = `Offered to serve ${a.ask_id} (${push("offer", q?.title ?? "", a.body, "offered", a.ask_id)})`; break; }
            case "say": line = `Said (${push("say", "", a.body, "said", null)})`; break;
            case "reply": line = `Replied to ${a.move_id} (${push("reply", "", a.body, "said", a.move_id)})`; break;
            case "leave_note": line = `Left a note (${push("note", "", a.body, "left", null)})`; break;
            case "post_task": line = `Task posted: ${a.title} (${push("task", a.title, a.spec, "open", null, { pledge: a.pledge })})`; break;
            case "claim": { const b = find(a.task_id); if (b) { b.state = "claimed"; Object.assign(b.fields as object, { claimed_by: r.view.summary.you_are, claimed_by_key: r.view.summary.you_key }); push("claim", b.title, "", "claimed", b.id); line = `Claimed: ${b.title}`; } break; }
            case "deliver": { const b = find(a.task_id); if (b) { b.state = "delivered"; push("delivery", b.title, a.summary, "delivered", b.id, { files: a.files }); line = `Delivered: ${b.title}`; } break; }
            case "accept": { const b = find(a.task_id); if (b) { b.state = "done"; const f = b.fields as Record<string, unknown>; push("receipt", b.title, `Completed: ${b.title}`, "issued", b.id, { to: f.claimed_by }); line = `Accepted: ${b.title}`; } break; }
            case "settle": { const b = find(a.task_id); if (b) { const f = b.fields as Record<string, unknown>; const side = b.by === r.view.summary.you_key ? "poster_says" : "doer_says"; f[side] = { agree: Boolean(a.agree), note: a.note ?? null }; push("settle", b.title, a.note ?? "", "said", b.id, { agree: a.agree }); line = `Said: ${b.title}`; } break; }
            case "post_offering": line = `Offered: ${a.title} (${push("offering", a.title, a.what, "offered", null, { pricing: a.pricing, terms: a.terms })})`; break;
            case "propose": line = `Proposed: ${a.direction} (${push("direction", a.direction, a.body ?? "", "open", null)})`; break;
            case "steer": { const d = find(a.direction_id); if (d) { const f = d.fields as Record<string, number>; f[a.move] = (f[a.move] ?? 0) + 1; push("steer", d.title, a.note ?? "", a.move, d.id); line = `Steered ${d.title}: ${a.move}`; } break; }
            case "synthesize": line = `Synthesis written (${push("synthesis", "Where it stands", a.body, "open", null)})`; break;
            case "set_charter": r.view.charter = a.text; push("charter", "The rules changed", "", "said", null); line = "Rules changed"; break;
            case "admit": r.view.members.push({ name: a.name, key: a.key, is_agent: false, agent_of: null, agent_of_key: null, joined: now, last_acted: null, mark: null, devices: [], slot: null }); push("admitted", a.name, "", "said", null); line = `Admitted: ${a.name}`; break;
            case "remove": { const m = r.view.members.find((x) => x.key === a.key); r.view.members = r.view.members.filter((x) => x.key !== a.key); push("removed", m?.name ?? "someone", a.reason ?? "", "said", null); line = "Removed"; break; }
            case "withdraw":
            case "erase": { const b = find(a.move_id); if (b) { const reason = a.reason ?? "withdrawn by its author"; const by = r.view.summary.you_are; Object.assign(b, { title: "", body: "" }); Object.assign(b.fields as object, { erased: { by, how: args.tool, reason } }); push("erased", "", `erased by ${by} under ${reason}`, "said", b.id, { move: b.id, how: args.tool }); line = `Erased the words of ${b.id}`; } break; }
            default: return { outcome: "error", message: `the preview doesn't play ${args.tool}` };
          }
          later(() => bump(args.id));
          return { outcome: "ok", text: line };
        }
        case "asks_send": {
          const thread = `t${Date.now()}`;
          const out = [];
          for (const id of args.rooms as string[]) {
            const r = spaceOf(id);
            if (!r) { out.push({ room: id, outcome: { outcome: "error", message: "no such Space" } }); continue; }
            const moveId = `ask-${++moveN}`;
            r.moves.push({ id: moveId, kind: "ask", author: r.view.summary.you_are, by: r.view.summary.you_key, member: null, erasable: false, agent_of: null, at: new Date().toISOString(), title: args.what, body: "", state: "open", parent: null, fields: { thread, needs: args.needs, ceiling: args.ceiling }, charter: "", hash: "" });
            out.push({ room: id, outcome: { outcome: "ok", text: `Asked (${moveId})` } });
            if (r.view.members.some((m) => m.name === "ada")) {
              setTimeout(() => {
                r.moves.push({ id: `offer-${++moveN}`, kind: "offer", author: "ada", by: "ada", member: null, erasable: false, agent_of: null, at: new Date().toISOString(), title: args.what, body: "I can look at that tomorrow. Say a bit more about what done looks like?", state: "offered", parent: moveId, fields: {}, charter: "", hash: "" });
                bump(id);
              }, 4000);
            }
          }
          return out;
        }
        case "spaces_watch": {
          const id = `space-${++scope}`;
          spaceWatches.set(id, { id: args.id, ch: args.onEvent as Chan });
          return id;
        }
        case "spaces_host": {
          const i = args.input;
          const id = `space-${Date.now()}`;
          const summary = { id, title: i.title, kind: i.kind, host: { kind: "outgoing", address: "127.0.0.1:4640" }, host_name: you.name, mine: true, online: true, you_are: you.name, you_key: you.key, you_account: null, fresh: false } as SpaceView["summary"];
          spaceRecs.push({ view: { summary, charter: i.charter, members: [{ name: you.name, key: you.key, is_agent: false, agent_of: null, agent_of_key: null, joined: new Date().toISOString(), last_acted: null, mark: null, devices: [], slot: null }], tools: spaceRecs[0]?.view.tools ?? [], before: [] }, moves: [], invite: encodeInvite({ host: summary.host, id, secret: `${id}-key`, title: i.title, kind: i.kind, host_name: you.name, charter: i.charter, verbs: [] }) });
          return { outcome: "hosted", id };
        }
        case "spaces_door": {
          const inv = decodeInvite(args.invite);
          if (!inv) throw new Error("that isn't an invite");
          return { usual_name: you.name, title: inv.title, kind: inv.kind, host_name: inv.host_name, host: inv.host, charter: inv.charter, verbs: inv.verbs, invited: Boolean(inv.secret), already_in: spaceRecs.some((r) => r.view.summary.id === inv.id) };
        }
        case "spaces_join": {
          const inv = decodeInvite(args.invite);
          if (!inv) return { outcome: "missing" };
          const as = args.appearAs as { as: string; name?: string };
          const name = as.as === "fresh" ? String(as.name) : you.name;
          const key = as.as === "fresh" ? `fresh-${Date.now()}` : you.key;
          if (as.as === "fresh") personas.push({ id: `persona-${personas.length + 1}`, name, usual: false, rooms: [inv.title] });
          await new Promise((res) => setTimeout(res, 1500));
          if (!spaceOf(inv.id)) {
            const summary = { id: inv.id, title: inv.title, kind: inv.kind, host: inv.host, host_name: inv.host_name, mine: false, online: true, you_are: name, you_key: key, you_account: null, fresh: as.as === "fresh" } as SpaceView["summary"];
            const now = new Date().toISOString();
            spaceRecs.push({
              view: { summary, charter: inv.charter, members: [{ name: inv.host_name, key: `host-${inv.id}`, is_agent: false, agent_of: null, agent_of_key: null, joined: now, last_acted: null, mark: null, devices: [], slot: null }, { name, key, is_agent: false, agent_of: null, agent_of_key: null, joined: now, last_acted: null, mark: null, devices: [], slot: null }], tools: spaceRecs[0]?.view.tools ?? [], before: [] },
              moves: [{ id: "admitted-1", kind: "admitted", author: inv.host_name, by: `host-${inv.id}`, member: null, erasable: false, agent_of: null, at: now, title: name, body: "", state: "said", parent: null, fields: {}, charter: "", hash: "" }],
              invite: null,
            });
          }
          return { outcome: "joined", id: inv.id, rules_match: true };
        }
        case "spaces_leave": {
          const at = spaceRecs.findIndex((r) => r.view.summary.id === args.id);
          if (at >= 0) spaceRecs.splice(at, 1);
          tabs = tabs.filter((t) => t.key !== `space:${args.id}`);
          generation++;
          emit("tabs://changed", snapshot());
          return null;
        }
        case "spaces_invite": {
          const r = spaceOf(args.id);
          return r?.invite ? { text: r.invite } : null;
        }
        case "knocks_watch": {
          knockCh = args.onEvent as Chan;
          later(() => { for (const k of knocks) knockCh?.onmessage({ event: "knock", knock: k }); });
          return `knocks-${++scope}`;
        }
        case "knocks_answer": {
          const at = knocks.findIndex((k) => k.knock_id === args.knockId);
          if (at >= 0) {
            const k = knocks.splice(at, 1)[0];
            const r = spaceOf(k.space);
            const now = new Date().toISOString();
            if (args.yes && r) {
              r.view.members.push({ name: k.name, key: `knock-${k.knock_id}`, is_agent: false, agent_of: null, agent_of_key: null, joined: now, last_acted: null, mark: null, devices: [], slot: null });
              r.moves.push({ id: `admitted-${++moveN}`, kind: "admitted", author: you.name, by: you.key, member: null, erasable: false, agent_of: null, at: now, title: k.name, body: "", state: "said", parent: null, fields: {}, charter: "", hash: "" });
              later(() => bump(k.space));
            }
          }
          return null;
        }
        case "table_tree": {
          const tb = tables[args.id];
          return tb ? { outcome: "tree", nodes: tb.nodes } : { outcome: "error", message: "you're not in that room" };
        }
        case "table_read": {
          const text = tables[args.id]?.files[args.path];
          return text === undefined ? { outcome: "error", message: `nothing at /${args.path} on this table` } : { outcome: "text", text, bytes: new TextEncoder().encode(text).length };
        }
        case "table_write": {
          const tb = (tables[args.id] ??= { nodes: [], files: {} });
          if (!(args.path in tb.files)) tb.nodes.push({ kind: "file", name: args.path, size: args.text.length, modified_at: null } as FileNode);
          tb.files[args.path] = args.text;
          return { outcome: "written" };
        }
        case "table_transfer": {
          const from = spaceOf(args.from);
          const to = spaceOf(args.to);
          if (!from || !to) return { outcome: "error", message: "no such room" };
          if (JSON.stringify(from.view.summary.host) !== JSON.stringify(to.view.summary.host)) return { outcome: "error", message: "those rooms run on different machines; a file moves between them through your Mac instead" };
          const text = tables[args.from]?.files[args.path] ?? "";
          const tb = (tables[args.to] ??= { nodes: [], files: {} });
          if (!(args.path in tb.files)) tb.nodes.push({ kind: "file", name: args.path, size: text.length, modified_at: null } as FileNode);
          tb.files[args.path] = text;
          return { outcome: "written" };
        }
        case "cards_watch":
          cardCh = args.onEvent as Chan;
          later(() => { for (const c of cards) cardCh?.onmessage({ event: "card", card: c }); });
          // Preview only: add ?card-withdrawn to the address to see the first card's agent stop waiting, as the app shows it.
          if (new URLSearchParams(location.search).has("card-withdrawn")) {
            setTimeout(() => {
              const c = cards.shift();
              if (!c) return;
              withdrawn.add(c.id);
              cardCh?.onmessage({ event: "withdrawn", id: c.id });
            }, 1500);
          }
          return `cards-${++scope}`;
        case "cards_answer": {
          if (withdrawn.has(args.id)) throw "that card was withdrawn: the agent stopped waiting, and nothing was done";
          const at = cards.findIndex((c) => c.id === args.id);
          if (at < 0) throw "that card was already answered";
          cards.splice(at, 1);
          cardCh?.onmessage({ event: "answered", id: args.id });
          return null;
        }
        case "door_tools":
          return fixture.door_tools;
        // Preview only: nothing listens here, and no token or helper file is made.
        case "local_agents_list":
          return localAgents;
        case "local_agents_add": {
          const id = String(args.name).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "agent";
          const a = { id, name: args.name, slot: `local/${id}`, connect_line: `claude mcp add-json diverge-${id} '{"type":"http","url":"http://127.0.0.1:4791/mcp","headersHelper":"\\"/preview/door/${id}-headers\\"","timeout":86400000}' --scope user`, added: new Date().toISOString() };
          localAgents.push(a);
          return a;
        }
        case "local_agents_new_key":
          return localAgents.find((a) => a.id === args.id) ?? null;
        case "local_agents_remove":
          localAgents.splice(localAgents.findIndex((a) => a.id === args.id), 1);
          return null;
        case "door_status":
          return localAgents.length ? { port: 4791, state: "listening" } : { port: null, state: "no_agents" };
        case "agent_bring_in":
          return null;
        case "machines_names":
          return {};
        case "machines_rename":
          return { [args.identity.kind === "outgoing" ? `outgoing:${args.identity.address}` : `incoming:${args.identity.identity}`]: args.name };
        case "machines_list":
          return machines;
        case "machines_add": {
          const i = args.input;
          const identity = i.way === "dial" ? { kind: "outgoing", address: i.address } : { kind: "incoming_unbrokered", identity: i.identity };
          const m = { identity, volumes: [], volumes_problem: null, added: new Date().toISOString(), name: null } as MachineView;
          machines.push(m);
          return m;
        }
        case "machines_remove": {
          const at = machines.findIndex((m) => JSON.stringify(m.identity) === JSON.stringify(args.identity));
          if (at >= 0) machines.splice(at, 1);
          return null;
        }
        case "views_list":
          return views;
        case "views_save": {
          const v = { ...args.view, id: args.view.id || `view-${Date.now()}`, saved: new Date().toISOString() };
          const at = views.findIndex((x) => x.id === v.id);
          if (at >= 0) views[at] = v;
          else views.push(v);
          return v;
        }
        case "views_delete":
          views.splice(views.findIndex((x) => x.id === args.id), 1);
          return null;
        case "tabs_snapshot":
          return snapshot();
        case "tabs_open": {
          const key = keyOf(args.tab);
          if (!tabs.some((t) => t.key === key)) tabs = [...tabs, { key, tab: args.tab }];
          focused = key;
          generation++;
          return snapshot();
        }
        case "tabs_close": {
          const at = tabs.findIndex((t) => t.key === args.key);
          if (at >= 0) {
            tabs = tabs.filter((t) => t.key !== args.key);
            if (focused === args.key) focused = tabs[Math.min(at, tabs.length - 1)]?.key ?? null;
            generation++;
          }
          return snapshot();
        }
        case "tabs_focus":
          focused = args.key;
          generation++;
          return snapshot();
        default:
          throw new Error(`the browser preview has no answer for ${cmd}`);
      }
    },
    { shouldMockEvents: true },
  );
}

function matchesType(entry: LogEntry, wire: string): boolean {
  const map: Record<string, string> = {
    user_text_content: "user_text",
    assistant_text_content: "text",
    assistant_reasoning: "reasoning",
    assistant_tool_call: "tool_call",
    tool_response: "tool_response",
    usage: "usage",
    notification: "notification",
    error: "error",
    active: "active",
    inactive: "inactive",
    assistant_refusal: "refusal",
  };
  return map[wire] === entry.item.kind;
}
